import type { Href } from 'expo-router';

import type { SessionUser } from '@/stores/session';

/** The setup wizard's first screen. Typed routes are generated by the dev server and lag behind newly added screens, so this is typed once here. */
export const SETUP_HREF = '/(app)/onboarding' as unknown as Href;

/** An association admin who has not finished (or skipped) the setup wizard. Role names are only used here, the one place architecture.md §7.4 allows. */
export function isSetupPending(user: SessionUser | null | undefined): boolean {
  return !!user && user.role === 'admin' && user.requiresOnboarding && !user.platformRole;
}

/** Where a signed-in person lands: the setup wizard for a new association's admin, Home for everyone else. */
export function landingHref(user: SessionUser | null | undefined): Href {
  if (isSetupPending(user)) return SETUP_HREF;
  // A standalone thrift group has no association Home: its Thrift tab (the Money route) is its home.
  if (user?.tenantKind === 'THRIFT_GROUP') return '/(app)/(tabs)/money';
  return '/(app)/(tabs)/home';
}

/** The association's free trial or subscription has ended, so the app is paused until it pays. */
export function isSubscriptionBlocked(user: SessionUser | null | undefined): boolean {
  return !!user && !user.platformRole && user.subscriptionAccess?.allowed === false;
}

/** Whole days left in the free trial when it is nearly over (3 or fewer), otherwise null. Drives the countdown banner. */
export function trialEndingInDays(user: SessionUser | null | undefined): number | null {
  const access = user?.subscriptionAccess;
  if (!user || user.platformRole || !access?.allowed || access.status !== 'TRIALING') return null;
  if (access.trialDaysLeft === null || access.trialDaysLeft > 3) return null;
  return access.trialDaysLeft;
}
